function telegramSupportPlan(update, settings) {
  const message = update?.message;
  const chatId = message?.chat?.id;
  const userId = message?.from?.id;
  const messageId = message?.message_id;
  if (
    !Number.isSafeInteger(chatId) ||
    !Number.isSafeInteger(userId) ||
    userId <= 0 ||
    !Number.isSafeInteger(messageId) ||
    messageId <= 0 ||
    message.sender_chat ||
    message.from?.is_bot !== false ||
    typeof message.text !== "string" ||
    !message.text.trim()
  )
    return null;
  const privateChat = message.chat.type === "private" && chatId === userId;
  const groupChat = ["group", "supergroup"].includes(message.chat.type) && chatId < 0;
  if (!privateChat && !groupChat) return null;
  const threadId = message.is_topic_message === true ? message.message_thread_id : null;
  if (
    message.is_topic_message === true &&
    (!groupChat || !Number.isSafeInteger(threadId) || threadId <= 0)
  )
    return null;
  const email = settings.requesters?.[chatId + ":" + userId];
  if (typeof email !== "string" || !/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,63}$/i.test(email))
    return null;
  if (
    !/^[1-9][0-9]{0,19}$/.test(settings.boardId) ||
    !/^[a-zA-Z0-9_]+$/.test(settings.refundGroup) ||
    !/^[a-zA-Z0-9_]+$/.test(settings.complaintGroup) ||
    settings.refundGroup === settings.complaintGroup ||
    !/^[1-9][0-9]{0,15}$/.test(settings.botId)
  )
    throw Error("Set the Telegram bot user ID and monday board and two distinct group IDs");
  const text = message.text;
  if (text.length > 8192) throw Error("Unexpected Telegram text length");
  const refund = text.includes("refund");
  const type = refund ? "refund" : "complaint";
  const subject = Array.from(text.replace(/\s+/g, " ").trim()).slice(0, 255).join("");
  const description =
    "<p>" +
    text
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replace(/\r\n?|\n/g, "<br>") +
    "</p>";
  const reply = refund
    ? "Hi, thanks for sending this. We will review your request for refund as soon as possible 💶 💵 💷"
    : "Hi, thanks for sending this. We will review your complaint as soon as possible 📬 ☀️ ✅";
  return {
    key: "telegram:" + settings.botId + ":" + chatId + ":" + messageId,
    chatId: String(chatId),
    messageId,
    botId: String(settings.botId),
    threadId,
    type,
    subject,
    boardId: String(settings.boardId),
    groupId: refund ? settings.refundGroup : settings.complaintGroup,
    reply,
    ticket: { email, subject, description, tags: [type], status: 3, priority: 1, source: 2 },
  };
}

const settings = {
  requesters: {},
  callbackUrl: "",
  botId: "",
  boardId: "",
  refundGroup: "",
  complaintGroup: "",
  freshdeskDomain: "",
};
const plan = telegramSupportPlan($input.first().json, settings);
if (!plan) return [];
if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(settings.freshdeskDomain))
  throw Error("Set the Freshdesk subdomain");
return [
  {
    json: {
      ...plan,
      ticketUrl: "https://" + settings.freshdeskDomain + ".freshdesk.com/api/v2/tickets",
    },
  },
];

function confirmFreshdeskSupportTicket(plan, body) {
  if (
    !Number.isSafeInteger(body?.id) ||
    body.id <= 0 ||
    body.subject !== plan.ticket.subject ||
    (typeof body.email === "string" && body.email.toLowerCase() !== plan.ticket.email.toLowerCase())
  ) {
    throw Error("Check Freshdesk before repeating ticket creation");
  }
  return { id: body.id, subject: body.subject };
}

if ($json.statusCode !== 201) throw Error("Check Freshdesk before repeating ticket creation");
return {
  json: confirmFreshdeskSupportTicket($("Authorize the support request").first().json, $json.body),
};

function confirmTelegramSupportReply(plan, result) {
  const messageId = result?.messageId ?? result?.message_id;
  const threadId = result?.messageThreadId ?? result?.message_thread_id;
  if (
    !Number.isSafeInteger(messageId) ||
    messageId <= 0 ||
    String(result.chat?.id) !== plan.chatId ||
    String(result.from?.id) !== plan.botId ||
    result.text !== plan.reply ||
    (plan.threadId !== null && threadId !== undefined && threadId !== plan.threadId)
  ) {
    throw Error("Check the original Telegram conversation before resending");
  }
  return messageId;
}

function mondaySupportItem(plan, ticket) {
  return {
    board_id: plan.boardId,
    group_id: plan.groupId,
    item_name: plan.type === "refund" ? ticket.subject : plan.subject,
  };
}

const plan = $("Authorize the support request").first().json;
const ticket = $("Confirm the Freshdesk ticket").first().json;
const replyId = confirmTelegramSupportReply(plan, $json.result ?? $json);
return { json: { ticketId: ticket.id, replyId, item: mondaySupportItem(plan, ticket) } };

function confirmMondaySupportItem(expected, item) {
  if (
    !/^[1-9][0-9]{0,19}$/.test(String(item?.id)) ||
    String(item.board?.id) !== expected.board_id ||
    item.group?.id !== expected.group_id ||
    item.name !== expected.item_name
  ) {
    throw Error("Check the configured monday group before creating another item");
  }
  return String(item.id);
}

if ($json.errors?.length)
  throw Error("Check the configured monday group before creating another item");
const receipt = $("Confirm the Telegram reply").first().json;
return {
  json: {
    type: $("Authorize the support request").first().json.type,
    chatId: $("Authorize the support request").first().json.chatId,
    messageId: $("Authorize the support request").first().json.messageId,
    ticketId: receipt.ticketId,
    telegramReplyId: receipt.replyId,
    mondayItemId: confirmMondaySupportItem(receipt.item, $json.data?.create_item),
  },
};
